using Newtonsoft.Json;using System;using System.Collections.Generic;using System.Globalization;using System.Net.Http;using System.Net.Http.Headers;using System.Text;using System.Threading.Tasks;namespace HDFCSmartGateway.Services { public class HdfcPaymentService {readonly HdfcSettings s;public HdfcPaymentService(HdfcSettings x){s=x;}public Task<string>CreateAsync(Models.CreatePaymentModel m){var d=new Dictionary<string,object>{{"order_id",m.OrderId},{"amount",m.Amount.ToString("0.00",CultureInfo.InvariantCulture)},{"currency","INR"},{"customer_id",String.IsNullOrWhiteSpace(m.CustomerId)?m.OrderId:m.CustomerId},{"payment_page_client_id",s.ClientId},{"action","paymentPage"},{"return_url",String.IsNullOrWhiteSpace(m.ReturnUrl)?s.ReturnUrl:m.ReturnUrl}};Add(d,"customer_email",m.CustomerEmail);Add(d,"customer_phone",m.CustomerPhone);Add(d,"first_name",m.FirstName);Add(d,"last_name",m.LastName);Add(d,"description",m.Description);return Send(HttpMethod.Post,s.SessionPath,d,String.IsNullOrWhiteSpace(m.CustomerId)?m.OrderId:m.CustomerId);}public Task<string>StatusAsync(string id,string customer){return Send(HttpMethod.Get,s.StatusPath.Replace("{orderId}",Uri.EscapeDataString(id)),null,customer);}async Task<string>Send(HttpMethod method,string path,object body,string route){using(var c=new HttpClient()){c.Timeout=TimeSpan.FromSeconds(30);var r=new HttpRequestMessage(method,s.BaseUrl.TrimEnd('/')+path);r.Headers.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes(s.ApiKey+":")));r.Headers.Add("x-merchantid",s.MerchantId);if(!String.IsNullOrWhiteSpace(route))r.Headers.Add(s.RoutingHeader,route);r.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));if(body!=null)r.Content=new StringContent(JsonConvert.SerializeObject(body),Encoding.UTF8,"application/json");using(r)using(var x=await c.SendAsync(r)){var text=await x.Content.ReadAsStringAsync();if(!x.IsSuccessStatusCode)throw new Exception("HDFC HTTP "+(int)x.StatusCode+": "+text);return text;}}}static void Add(IDictionary<string,object>d,string k,string v){if(!String.IsNullOrWhiteSpace(v))d[k]=v;}}}